1	// Red-first fixtures for this pack's check, plus a guard on the pack manifest.
2	//
3	// The check reads its files through the engine's `ctx`, so the fixtures here are
4	// tiny in-memory contexts ({ files, read }) — no temp dirs, no mount, and the
5	// same shape the real runner passes (engine/checks/helpers/repo-context.mjs).
6	// The last rule test runs it against this repo's ACTUAL package.json and
7	// scripts/verify.sh, which is what makes the check a live gate rather than a
8	// self-fulfilling unit test.
9	
10	import { test } from "node:test";
11	import assert from "node:assert/strict";
12	import { readFileSync, existsSync } from "node:fs";
13	import { execFileSync } from "node:child_process";
14	import { fileURLToPath } from "node:url";
15	import path from "node:path";
16	
17	import pack from "./pack.mjs";
18	import rule from "./test-globs-in-step.mjs";
19	import verifyShSourceDirsRule from "./verify-sh-source-dirs.mjs";
20	import noStrayPackageJsonRule from "./no-stray-package-json.mjs";
21	
22	const __dirname = path.dirname(fileURLToPath(import.meta.url));
23	const REPO = path.resolve(__dirname, "../../../..");
24	
25	/** The repo's real tracked files, for a live-gate test against actual content. */
26	function trackedFiles() {
27	  return execFileSync("git", ["ls-files"], { cwd: REPO, encoding: "utf8" })
28	    .split("\n")
29	    .filter(Boolean);
30	}
31	
32	const GLOBS = "plan/lib/__tests__/*.test.mjs .claudinite/local/packs/*/*.test.mjs";
33	
34	/** A context over an in-memory {path: string} map, matching the engine's ctx. */
35	function ctxOf(tree) {
36	  const files = Object.keys(tree);
37	  return { files, read: (p) => (p in tree ? tree[p] : null) };
38	}
39	
40	const verifyScript = (globs) => `#!/usr/bin/env bash
41	set -euo pipefail
42	
43	step "Unit tests — node --test"
44	# Keep in step with the "test" script in package.json.
45	node --test ${globs}
46	
47	step "JavaScript syntax — node --check"
48	`;
49	
50	const packageJson = (globs) =>
51	  JSON.stringify({ name: "edfringenow", scripts: { test: `node --test ${globs}`, verify: "bash scripts/verify.sh" } });
52	
53	test("identical glob lists produce no findings", () => {
54	  const out = rule.run(ctxOf({
55	    "package.json": packageJson(GLOBS),
56	    "scripts/verify.sh": verifyScript(GLOBS),
57	  }));
58	  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
59	});
60	
61	test("the same globs in a different order still pass", () => {
62	  const out = rule.run(ctxOf({
63	    "package.json": packageJson(".claudinite/local/packs/*/*.test.mjs plan/lib/__tests__/*.test.mjs"),
64	    "scripts/verify.sh": verifyScript(GLOBS),
65	  }));
66	  assert.deepEqual(out, []);
67	});
