69	test("a glob added to package.json but not to verify.sh is reported", () => {
70	  // The exact regression this guards: a new local pack's pack.test.mjs is wired
71	  // into `npm test`, the verify.sh copy is forgotten, and CI never runs it.
72	  const out = rule.run(ctxOf({
73	    "package.json": packageJson(`${GLOBS} .claudinite/local/packs/edfringe/tasks/*/*.test.mjs`),
74	    "scripts/verify.sh": verifyScript(GLOBS),
75	  }));
76	  assert.equal(out.length, 1);
77	  assert.equal(out[0].rule, "edfringe-test-globs-in-step");
78	  assert.equal(out[0].severity, "blocking");
79	  assert.equal(out[0].file, "scripts/verify.sh");
80	  assert.match(out[0].what, /drifted apart/);
81	  assert.match(out[0].what, /only in package\.json: \.claudinite\/local\/packs\/edfringe\/tasks\/\*\/\*\.test\.mjs/);
82	  assert.ok(out[0].fix.includes("npm test"), "the fix must name the single-source escape hatch");
83	});
84	
85	test("a glob added to verify.sh but not to package.json is reported", () => {
86	  const out = rule.run(ctxOf({
87	    "package.json": packageJson(GLOBS),
88	    "scripts/verify.sh": verifyScript(`${GLOBS} scraper/__tests__/*.test.mjs`),
89	  }));
90	  assert.equal(out.length, 1);
91	  assert.match(out[0].what, /only in scripts\/verify\.sh: scraper\/__tests__\/\*\.test\.mjs/);
92	});
