94	test("verify.sh dropping `node --test` entirely is reported", () => {
95	  const out = rule.run(ctxOf({
96	    "package.json": packageJson(GLOBS),
97	    "scripts/verify.sh": "#!/usr/bin/env bash\nset -euo pipefail\nnode --check js/app.js\n",
98	  }));
99	  assert.equal(out.length, 1);
100	  assert.match(out[0].what, /runs no unit tests at all/);
101	});
