103	test("verify.sh delegating to `npm test` is single-sourced, so the check stands down", () => {
104	  const out = rule.run(ctxOf({
105	    "package.json": packageJson(GLOBS),
106	    "scripts/verify.sh": "#!/usr/bin/env bash\nset -euo pipefail\nnpm test\n",
