111	test("a tree missing either file ⇒ no findings (relevance-first)", () => {
112	  assert.deepEqual(rule.run(ctxOf({ "package.json": packageJson(GLOBS) })), []);
113	  assert.deepEqual(rule.run(ctxOf({ "scripts/verify.sh": verifyScript(GLOBS) })), []);
114	  assert.deepEqual(rule.run(ctxOf({ "README.md": "hi" })), []);
