117	test("a package.json with no test script is not this check's business", () => {
118	  assert.deepEqual(rule.run(ctxOf({
119	    "package.json": JSON.stringify({ scripts: {} }),
120	    "scripts/verify.sh": verifyScript(GLOBS),
121	  })), []);
122	});
