124	test("this repo's own package.json and verify.sh are in step", () => {
125	  // The live gate: the real files, read off disk.
126	  const present = ["package.json", "scripts/verify.sh"].filter((f) => existsSync(path.join(REPO, f)));
127	  assert.equal(present.length, 2, "expected both files to be present");
128	
129	  const out = rule.run({
130	    files: present,
131	    read: (p) => (present.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
132	  });
