141	  `js_files=$(git ls-files ${dirs.map((d) => `'${d}'`).join(" ")} | { grep -E '\\.m?js$' || true; })\n`;
142	
143	test("every top-level source dir named in verify.sh ⇒ no findings", () => {
144	  const out = verifyShSourceDirsRule.run(ctxOf({
145	    "scripts/verify.sh": verifyShWithDirs("js", "plan", "scripts", "shared"),
146	    "js/app.js": "",
147	    "plan/plan.js": "",
148	    "scripts/bump-version.mjs": "",
149	    "shared/geo.js": "",
150	  }));
151	  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
152	});
