154	test("a top-level dir with .mjs source left off the git ls-files list is reported", () => {
155	  // The exact regression this guards: scripts/bump-version.mjs shipped (#81) with
156	  // scripts/ never added to verify.sh's syntax-check glob, so it was never
157	  // node --check'd in the pre-commit hook or in CI.
158	  const out = verifyShSourceDirsRule.run(ctxOf({
159	    "scripts/verify.sh": verifyShWithDirs("js", "plan", "shared"),
160	    "js/app.js": "",
161	    "scripts/bump-version.mjs": "",
162	  }));
163	  assert.equal(out.length, 1);
164	  assert.equal(out[0].rule, "edfringe-verify-sh-covers-source-dirs");
165	  assert.equal(out[0].severity, "blocking");
166	  assert.equal(out[0].file, "scripts/verify.sh");
167	  assert.match(out[0].what, /^scripts has committed \.js\/\.mjs files/);
168	  assert.match(out[0].fix, /add 'scripts' to the `git ls-files` call/);
169	});
