171	test("multiple missing dirs are named together, sorted", () => {
172	  const out = verifyShSourceDirsRule.run(ctxOf({
173	    "scripts/verify.sh": verifyShWithDirs("plan"),
174	    "shared/geo.js": "",
175	    "js/app.js": "",
176	  }));
177	  assert.equal(out.length, 1);
178	  assert.match(out[0].what, /^js, shared /);
