181	test("hidden dirs and bare top-level files are never flagged", () => {
182	  const out = verifyShSourceDirsRule.run(ctxOf({
183	    "scripts/verify.sh": verifyShWithDirs("js", "plan", "scripts", "shared"),
184	    ".claudinite/shared/engine/x.mjs": "",
185	    "build-info.js": "",
186	  }));
187	  assert.deepEqual(out, []);
188	});
