190	test("no verify.sh in the tree ⇒ no findings (relevance-first)", () => {
191	  assert.deepEqual(verifyShSourceDirsRule.run(ctxOf({ "shared/geo.js": "" })), []);
192	});
193	
194	test("this repo's verify.sh covers every real top-level source dir", () => {
195	  // The live gate: every tracked file, read straight from git.
196	  const files = trackedFiles();
197	  const out = verifyShSourceDirsRule.run({
198	    files,
199	    read: (p) => (files.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
