242	test("this repo carries no stray package.json", () => {
243	  // The live gate: every tracked file, read straight from git.
244	  const files = trackedFiles();
245	  const out = noStrayPackageJsonRule.run({
246	    files,
247	    read: (p) => (files.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
