253	  assert.equal(pack.id, "edfringe");
254	  assert.equal(pack.detect, null, "a local pack is never fingerprinted");
255	  assert.equal(pack.marker, null);
256	  assert.equal(pack.prose, "RULES.md");
257	  assert.ok(pack.rules.includes(rule), "the check must be listed on the manifest or it never runs");
258	  assert.ok(pack.rules.includes(verifyShSourceDirsRule), "the check must be listed on the manifest or it never runs");
259	  assert.ok(pack.rules.includes(noStrayPackageJsonRule), "the check must be listed on the manifest or it never runs");
