1	// Dependency-free by design: a local pack's checks must load without the
2	// vendored mount, so this returns plain finding objects rather than importing
3	// engine/checks/helpers/findings.mjs.
4	
5	const DAY_FILE = /^data\/days\/\d{4}-\d{2}-\d{2}\.json$/;
6	const MASTER = 'data/normalized/shows.min.json';
7	const LOOKUPS = 'data/venues.json';
8	
9	// Per file, so one systematically shifted lookup list reports a readable handful
10	// instead of thousands of identical lines.
11	const MAX_PER_FILE = 5;
12	
13	const rule = {
14	  id: 'edfringe-lookup-indices',
15	  severity: 'blocking',
16	  description:
17	    'Every genre / room / subgenre / ticket-status / age-restriction index in the committed day files and shows.min.json resolves inside the matching data/venues.json lookup list',
18	  why:
19	    'the wire format ships the lookup lists once and references them by position, so an index the list no longer has (or a list regenerated without its day files) mislabels shows silently — the client renders undefined, or worse, the neighbouring genre',
20	  doc: 'scraper/README.md',
21	
22	  run(ctx) {
23	    const raw = ctx.read(LOOKUPS);
24	    if (raw === null) return []; // relevance-first: no data layer in this repo state
25	
26	    let lookups;
27	    try {
28	      lookups = JSON.parse(raw);
29	    } catch (e) {
30	      return [finding(LOOKUPS, `data/venues.json is not valid JSON: ${e.message}`,
31	        'regenerate it with `python3 scraper/normalize.py` rather than hand-editing')];
32	    }
33	
34	    const out = [];
35	    const len = (name) => (Array.isArray(lookups[name]) ? lookups[name].length : 0);
36	
37	    // The producer is scraper/normalize.py (build_day_files / minify_master); the
38	    // consumers are js/app.js adaptShow and plan/lib/hydrate.js rehydrateShows.
39	    // Day-file field -> venues.json list. `room` and `ts` carry -1 for "unknown"
40	    // (normalize.py writes -1; adaptShow resolves it to no room / no status).
41	    const dayFields = [
42	      ['genre', 'genres', false],
43	      ['room', 'rooms', true],
44	      ['ts', 'ticketStatuses', true],
45	    ];
46	    // shows.min.json's shorter keys, same lists.
47	    const masterFields = [
48	      ['g', 'genres', false],
49	      ['rm', 'rooms', true],
50	      ['ar', 'ageRestrictions', true],
51	    ];
52	
53	    function finding(file, what, fix) {
54	      return {
55	        rule: rule.id,
56	        severity: rule.severity,
57	        file,
58	        line: null,
59	        what,
60	        why: rule.why,
61	        fix,
62	        doc: rule.doc,
63	      };
64	    }
65	
66	    function checkIndex(found, label, value, list, allowMissing) {
67	      if (value === undefined || value === null) return;
68	      if (!Number.isInteger(value)) {
69	        found.push([label, `${label} is ${JSON.stringify(value)}, not an integer index`]);
70	        return;
71	      }
72	      if (allowMissing && value === -1) return;
73	      if (value < 0 || value >= len(list)) {
74	        found.push([label, `${label} = ${value} is outside venues.json "${list}" (${len(list)} entries)`]);
75	      }
76	    }
77	
78	    function checkRecords(file, records, fields, subKey, statusOf) {
79	      const found = [];
80	      records.forEach((rec, i) => {
81	        if (found.length >= MAX_PER_FILE) return;
82	        if (!rec || typeof rec !== 'object') return;
83	        const at = `record #${i}${rec.title ? ` (${rec.title})` : rec.t ? ` (${rec.t})` : ''}`;
84	        for (const [key, list, allowMissing] of fields) {
85	          checkIndex(found, `${at} ${key}`, rec[key], list, allowMissing);
86	        }
87	        for (const s of rec[subKey] ?? []) {
88	          checkIndex(found, `${at} ${subKey}[]`, s, 'subgenres', false);
89	        }
90	        for (const [label, value] of statusOf(rec, at)) {
91	          checkIndex(found, label, value, 'ticketStatuses', true);
92	        }
93	      });
94	      for (const [, what] of found.slice(0, MAX_PER_FILE)) {
95	        out.push(finding(file, what,
96	          'regenerate the data layer together — `python3 scraper/normalize.py` (add --merge for a top-up) rewrites venues.json and every day file from the master in one pass; never edit either side alone'));
97	      }
98	    }
99	
100	    for (const file of ctx.files.filter((f) => DAY_FILE.test(f))) {
101	      const text = ctx.read(file);
102	      if (text === null) continue;
103	      let records;
104	      try {
105	        records = JSON.parse(text);
106	      } catch (e) {
107	        out.push(finding(file, `day file is not valid JSON: ${e.message}`,
108	          'regenerate it with `python3 scraper/normalize.py`'));
109	        continue;
110	      }
111	      if (!Array.isArray(records)) {
112	        out.push(finding(file, 'a day file must be a plain array of show records',
113	          'regenerate it with `python3 scraper/normalize.py`'));
114	        continue;
115	      }
116	      // A day record is one performance: its ticket status is the flat `ts`,
117	      // already covered by dayFields, so no per-performance list here.
118	      checkRecords(file, records, dayFields, 'subs', () => []);
119	    }
120	
121	    const masterText = ctx.files.includes(MASTER) ? ctx.read(MASTER) : null;
122	    if (masterText !== null) {
123	      let records;
124	      try {
125	        records = JSON.parse(masterText);
126	      } catch (e) {
127	        out.push(finding(MASTER, `shows.min.json is not valid JSON: ${e.message}`,
128	          'regenerate it with `python3 scraper/normalize.py`'));
129	        return out;
130	      }
131	      if (Array.isArray(records)) {
132	        // The master keeps every performance, each with its own ticket status `t`.
133	        checkRecords(MASTER, records, masterFields, 'sg', (rec, at) =>
134	          (rec.p ?? []).map((p, j) => [`${at} p[${j}].t`, p && p.t]));
135	      }
136	    }
137	
138	    return out;
139	  },
140	};
141	
142	export default rule;
143

