57	test("a genre index past the end of venues.json genres is reported", () => {
58	  // The exact regression this guards: someone shrinks/reorders a lookup list (or
59	  // hand-edits a day file) and every affected card silently mislabels.
60	  const out = rule.run(ctxOf({
61	    "data/venues.json": LOOKUPS,
