  assert.equal(out.length, 1);
});

test("a normalizer with no --selftest to run ⇒ no findings (relevance-first)", () => {
  assert.deepEqual(selftestRule.run(textCtx({
    "scraper/normalize.py": "def main():\n    pass\n",
