    'a performance can be soldOut: false and still have nothing to sell online (NO_ALLOCATION_CONTACT_VENUE) — a denylist that names only SOLD_OUT renders those shows as buyable, sending people to a basket that cannot take them',
  doc: 'RULES.md',

  run(ctx) {
    const out = [];

    for (const file of ctx.files.filter((f) => SOURCE.test(f) && !NOT_SOURCE(f)).sort()) {
      const text = ctx.read(file);
      if (text === null) continue;

      SET_LITERAL.lastIndex = 0;
      for (const m of text.matchAll(SET_LITERAL)) {
        const elements = elementsOf(m[1]);
        // Not a status denylist unless it denies the obvious one.
        if (!elements.includes(SOLD_OUT)) continue;
        if (elements.includes(NO_ALLOCATION)) continue;

        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: text.slice(0, m.index).split('\n').length,
          what: `this availability denylist lists ${SOLD_OUT} but not ${NO_ALLOCATION}`,
          why: rule.why,
          fix: `add "${NO_ALLOCATION}" to the set — availability keys off ticketStatus, and that status means the online allocation is gone even when soldOut is false`,
          doc: rule.doc,
        });
      }
    }

    return out;
  },
};

export default rule;

