// --- ticket-status-unavailable: every availability denylist must deny
// NO_ALLOCATION_CONTACT_VENUE as well as SOLD_OUT ---

const bothStatuses = `const NO_TICKETS_STATUSES = new Set(["SOLD_OUT", "NO_ALLOCATION_CONTACT_VENUE"]);\n`;
const onlySoldOut = `const NO_TICKETS_STATUSES = new Set(["SOLD_OUT"]);\n`;

test("a denylist naming both statuses ⇒ no findings", () => {
  const out = ticketStatusRule.run(textCtx({
    "js/app.js": `// availability\n${bothStatuses}`,
    "plan/lib/availability.js": `export const UNAVAILABLE_STATUSES = new Set([\n  "SOLD_OUT", "OFF_SALE",\n  // no online allocation left — you'd have to contact the venue\n  "NO_ALLOCATION_CONTACT_VENUE",\n]);\n`,
  }));
  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
});

test("a denylist that lists SOLD_OUT but drops NO_ALLOCATION_CONTACT_VENUE is reported", () => {
  // The exact regression this guards: a performance is soldOut:false with no
  // online allocation left, and the card renders it as buyable.
  const out = ticketStatusRule.run(textCtx({ "js/app.js": `// line one\n${onlySoldOut}` }));
  assert.equal(out.length, 1);
  assert.equal(out[0].rule, "edfringe-ticket-status-unavailable");
  assert.equal(out[0].severity, "blocking");
  assert.equal(out[0].file, "js/app.js");
  assert.equal(out[0].line, 2, "the finding must point at the denylist, not the top of the file");
  assert.match(out[0].what, /lists SOLD_OUT but not NO_ALLOCATION_CONTACT_VENUE/);
  assert.ok(out[0].fix.includes("NO_ALLOCATION_CONTACT_VENUE"), "the fix must name the status to add");
});

test("the planner's own denylist is held to the same bar", () => {
  const out = ticketStatusRule.run(textCtx({
    "js/app.js": bothStatuses,
    "plan/lib/availability.js": `export const UNAVAILABLE_STATUSES = new Set(["SOLD_OUT", "CANCELLED"]);\n`,
  }));
  assert.equal(out.length, 1);
  assert.equal(out[0].file, "plan/lib/availability.js");
});

test("status names in switch arms are not denylists, so they are never flagged", () => {
  // Why this check parses `new Set([...])` instead of grepping: plan.js maps the
  // same status names to colours and labels all over, and none of that is a
  // denylist. A grep for SOLD_OUT-without-NO_ALLOCATION would light up here.
  const out = ticketStatusRule.run(textCtx({
    "plan/plan.js": `function segClass(p) {\n  switch (p.status) {\n    case "SOLD_OUT": return "seg-sold";\n    case "TWO_FOR_ONE": return "seg-offer";\n  }\n}\n`,
  }));
  assert.deepEqual(out, []);
});

test("a Set with no SOLD_OUT is not an availability denylist", () => {
  const out = ticketStatusRule.run(textCtx({
    "js/app.js": `const NON_TICKETED = new Set(["FREE_NON_TICKETED"]);\n`,
  }));
  assert.deepEqual(out, []);
});

